// Build a plausible struct stat without using FUZZ_PARAM(struct stat) which is unsupported.
// We zero-initialize, then fill a subset of common POSIX fields to look sane.
struct stat sb = {};

// Choose a plausible file type/mode: either regular file 0644 or directory 0755
unsigned int pick = *FUZZ_PARAM(unsigned int);
if ((pick & 1u) == 0u) {
    // 0100644 -> regular file with 0644 perms
    sb.st_mode = 0100644;
} else {
    // 0040755 -> directory with 0755 perms
    sb.st_mode = 0040755;
}

// Ensure link count at least 1
sb.st_nlink = 1;

// Size bounded to keep values small and reasonable
sb.st_size = static_cast<decltype(sb.st_size)>(*FUZZ_PARAM(unsigned int) % 2048u);

// Set a common block size and derive block count conservatively
// (512-byte blocks is conventional for st_blocks)
{
    auto sz = static_cast<unsigned long long>(sb.st_size);
    unsigned long long blocks = (sz + 511ull) / 512ull;
    // Assign with implicit conversion to st_blocks' type
    sb.st_blocks = static_cast<decltype(sb.st_blocks)>(blocks);
}

// Use a typical page-sized block size if available in this build
sb.st_blksize = sb.st_blksize ? sb.st_blksize : 4096;

// Populate a few more identifiers with small values
sb.st_uid = static_cast<decltype(sb.st_uid)>(*FUZZ_PARAM(unsigned int) % 32768u);
sb.st_gid = static_cast<decltype(sb.st_gid)>(*FUZZ_PARAM(unsigned int) % 32768u);

// Generate a write-counter token (opaque semantics)
uint64_t wrctr = (uint64_t)(*FUZZ_PARAM(unsigned long long));

// Invoke the target API with a non-NULL, plausibly-populated stat buffer
cache_add_attr(path, &sb, wrctr);

